`uvm_info("write_drv STIM", tr.convert2string(), UVM_HIGH)
dout = next_dout;
if (!tr.rst_n) {next_dout,dout} = '0;
else if ( tr.ld) next_dout = tr.din;
else if ( tr.inc) next_dout++;
tr.dout = dout;
void'(expfifo.try_put(tr));
